CREATE POLICY "push_delivery_recipient_insert" ON "push_deliveries" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("push_deliveries"."event_id"=NULLIF(current_setting('rove.push_event',true),'')::uuid AND "push_deliveries"."installation_id"=NULLIF(current_setting('rove.push_installation',true),'')::uuid AND "push_deliveries"."revision"=NULLIF(current_setting('rove.push_revision',true),'')::int AND "push_deliveries"."state"='pending' AND "push_deliveries"."attempts"=0 AND "push_deliveries"."receipt_attempts"=0 AND "push_deliveries"."receipt_id" IS NULL AND "push_deliveries"."accepted_at" IS NULL AND "push_deliveries"."lease_token" IS NULL AND "push_deliveries"."locked_until" IS NULL AND "push_deliveries"."last_error" IS NULL);--> statement-breakpoint
