CREATE POLICY "push_delivery_worker_update" ON "push_deliveries" AS PERMISSIVE FOR UPDATE TO public USING ("push_deliveries"."id"=NULLIF(current_setting('rove.push_delivery',true),'')::uuid) WITH CHECK ("push_deliveries"."id"=NULLIF(current_setting('rove.push_delivery',true),'')::uuid);--> statement-breakpoint
